import{_ as d,r as o,o as n,c as s,e as r,d as e}from"./chunks/framework.8NMv9ABN.js";const m=JSON.parse('{"title":"Terminal","description":"","frontmatter":{},"headers":[],"relativePath":"uk/tools/terminal.md","filePath":"uk/tools/terminal.md"}'),i={name:"uk/tools/terminal.md"};function l(h,t,b,p,c,g){const a=o("Screenshot");return n(),s("div",null,[t[0]||(t[0]=r('<h1 id="terminal" tabindex="-1">Terminal <a class="header-anchor" href="#terminal" aria-label="Permalink to &quot;Terminal&quot;">​</a></h1><p>Terminal — це торговий термінал із глибиною ринку. Це єдиний інструмент Warden, який не є монітором: він підключається до біржового акаунта за наданими вами ключами і розміщує, скасовує та закриває реальні ордери реальними коштами.</p><p>Він працює з п&#39;ятьма майданчиками на трьох біржах:</p><table tabindex="0"><thead><tr><th>Майданчик</th><th>Біржа</th><th>Ринок</th></tr></thead><tbody><tr><td>Hyperliquid</td><td>Hyperliquid</td><td>Безстрокові контракти</td></tr><tr><td>Binance Perp</td><td>Binance</td><td>Безстрокові ф&#39;ючерси</td></tr><tr><td>Binance Spot</td><td>Binance</td><td>Спот</td></tr><tr><td>Bybit Perp</td><td>Bybit</td><td>Безстрокові ф&#39;ючерси</td></tr><tr><td>Bybit Spot</td><td>Bybit</td><td>Спот</td></tr></tbody></table><div class="danger custom-block"><p class="custom-block-title">Це незавершений proof of concept</p><p>Terminal — тестовий інструмент, а не основний продукт. Він містить помилки, не є пріоритетом розробки й може поводитися непередбачувано. Підтримка Binance та Bybit новіша за Hyperliquid і відповідно менш перевірена.</p><p>Він також торгує реальними грошима:</p><ul><li><strong>Немає жодного підтвердження.</strong> Один клік по драбині цін миттєво надсилає ордер. Немає ані «ви впевнені?», ані попереднього перегляду, ані скасування.</li><li><strong>Потрібні торгові ключі</strong> — приватний ключ підписувача на Hyperliquid, API ключ і секрет із дозволом на торгівлю на Binance та Bybit.</li><li><strong>Збитки реальні та незворотні.</strong> Помилка в незавершеному введенні ордерів коштує справжніх грошей.</li></ul><p>Якщо ви все ж користуєтесь ним — беріть акаунт, який не шкода втратити, і спершу вивчіть поведінку кліків на найменшому розмірі ордера.</p><p>Якщо ви прийшли до Warden заради моніторингу, цей інструмент вам не потрібен взагалі. Усі інші інструменти читають лише публічні дані, ніколи не запитують ключів і не можуть торгувати.</p></div>',5)),e(a,{src:"terminal",alt:"Вікно Terminal із кількома драбинами стакана",caption:"Вікно Terminal — по драбині на панель"}),t[1]||(t[1]=r('<p>Усе нижче описує поточну поведінку застосунку. Оскільки це proof of concept, очікуйте змін.</p><h2 id="налаштування" tabindex="-1">Налаштування <a class="header-anchor" href="#налаштування" aria-label="Permalink to &quot;Налаштування&quot;">​</a></h2><p>Відкрийте вкладку <strong>Terminal</strong> у головному вікні. Налаштування згруповані у згортні секції; почніть із <strong>Exchange API keys</strong>.</p><h3 id="exchange-api-keys" tabindex="-1">Exchange API keys <a class="header-anchor" href="#exchange-api-keys" aria-label="Permalink to &quot;Exchange API keys&quot;">​</a></h3><p>По одному набору ключів на біржу. Кожен зберігається у <strong>сховищі облікових даних ОС</strong> (Windows Credential Manager), ніколи у файлі налаштувань Warden, і використовується лише вікном термінала.</p><h4 id="hyperliquid" tabindex="-1">Hyperliquid <a class="header-anchor" href="#hyperliquid" aria-label="Permalink to &quot;Hyperliquid&quot;">​</a></h4><p>Hyperliquid підписує нативно й потребує двох полів:</p><table tabindex="0"><thead><tr><th>Поле</th><th>Що це</th></tr></thead><tbody><tr><td><strong>Private key</strong></td><td>Приватний ключ API-гаманця — <code>0x…</code>, 64 шістнадцяткові символи</td></tr><tr><td><strong>Account address</strong></td><td><code>0x…</code> — адреса вашого основного акаунта або сховища</td></tr></tbody></table><p>Вказівка самого застосунку: <em>приватний ключ API-гаманця (Hyperliquid → API). Вкажіть адресу основного акаунта або сховища, якщо ключ належить агентському гаманцю.</em></p><p>Для показу зберігаються лише останні 4 символи ключа. Адреса не є секретом, тому при редагуванні вона підставляється автоматично; ключ — ніколи.</p><h4 id="binance" tabindex="-1">Binance <a class="header-anchor" href="#binance" aria-label="Permalink to &quot;Binance&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Поле</th><th>Що це</th></tr></thead><tbody><tr><td><strong>API key</strong></td><td>Ваш API ключ Binance</td></tr><tr><td><strong>API secret</strong></td><td>Його секрет</td></tr></tbody></table><p>Вказівка застосунку: <em>потрібні «Enable Futures» та «Enable Spot &amp; Margin Trading». <strong>Ніколи не вмикайте виведення коштів.</strong></em></p><h4 id="bybit" tabindex="-1">Bybit <a class="header-anchor" href="#bybit" aria-label="Permalink to &quot;Bybit&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Поле</th><th>Що це</th></tr></thead><tbody><tr><td><strong>API key</strong></td><td>Ваш API ключ Bybit</td></tr><tr><td><strong>API secret</strong></td><td>Його секрет</td></tr></tbody></table><p>Вказівка застосунку: <em>ключ уніфікованого акаунта з дозволом «Trade». <strong>Ніколи не вмикайте виведення коштів.</strong></em></p><div class="warning custom-block"><p class="custom-block-title">Ніколи не вмикайте дозвіл на виведення коштів</p><p>Terminal потребує лише торгівлі. API ключ із правом виведення перетворює будь-яку помилку, витік файлу налаштувань чи компрометацію вашого комп&#39;ютера на спустошений акаунт, а не на невдалу угоду.</p><p>Warden ніколи не запитує дозволу на виведення і не має функції, яка його використовує.</p></div><h4 id="test" tabindex="-1">Test <a class="header-anchor" href="#test" aria-label="Permalink to &quot;Test&quot;">​</a></h4><p>Ключі Binance і Bybit мають кнопку <strong>Test</strong> (⟳). Нею варто скористатися — це не перевірка формату. Вона передає ключ у робочий процес і виконує реальний автентифікований запит балансу, тож хибний ключ, відсутній дозвіл на торгівлю чи збитий системний годинник виявляються тут, а не в момент спроби торгувати.</p><p>Кожна біржа звітує окремим рядком, бо один ключ може бути увімкнений для ф&#39;ючерсів, але не для споту.</p><h4 id="видалення-ключа" tabindex="-1">Видалення ключа <a class="header-anchor" href="#видалення-ключа" aria-label="Permalink to &quot;Видалення ключа&quot;">​</a></h4><p>Кнопка <strong>✕</strong> видаляє ключ зі сховища облікових даних ОС і прибирає його з робочого процесу, який міг уже його тримати, тож видалений ключ не продовжить працювати до наступного перезавантаження.</p><div class="info custom-block"><p class="custom-block-title">Оновлення зі старішої збірки</p><p>Попередні версії тримали до п&#39;яти іменованих акаунтів Hyperliquid з вибором активного. Це згорнулося в один набір ключів на біржу, описаний вище.</p><p>При першому запуску ключ і адреса активного акаунта переносяться автоматично. Ключі решти акаунтів <strong>не видаляються</strong> — вони лишаються у сховищі облікових даних ОС під старими ідентифікаторами, недосяжні з інтерфейсу, але відновлювані вручну. Їхні ідентифікатори один раз записуються в лог застосунку під час міграції.</p></div>',23)),e(a,{src:"terminal-settings",alt:"Налаштування розміру ордера, стрічки угод і клавіш Terminal",caption:"Налаштування Terminal — розмір ордера, стрічка, клавіші"}),t[2]||(t[2]=r('<h3 id="order" tabindex="-1">Order <a class="header-anchor" href="#order" aria-label="Permalink to &quot;Order&quot;">​</a></h3><h4 id="order-size-usd" tabindex="-1">Order size (USD) <a class="header-anchor" href="#order-size-usd" aria-label="Permalink to &quot;Order size (USD)&quot;">​</a></h4><p>П&#39;ять редагованих пресетів номінального розміру в доларах, що виставляється за клік. За замовчуванням: <code>$11</code>, <code>$50</code>, <code>$500</code>, <code>$1000</code>, <code>$4000</code>.</p><p>Клацніть пресет, щоб обрати його й змінити значення на місці. Обраний пресет — це розмір, який використає кожен клік; пресети також обираються з клавіатури — див. <a href="#клавіші">Клавіші</a>.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Активний пресет діє на кожен клік по драбині. Змінивши його, ви змінюєте розмір наступного ордера — перевіряйте, який пресет активний, перш ніж клацати.</p></div><h3 id="trade-tape" tabindex="-1">Trade tape <a class="header-anchor" href="#trade-tape" aria-label="Permalink to &quot;Trade tape&quot;">​</a></h3><h4 id="tape-style" tabindex="-1">Tape style <a class="header-anchor" href="#tape-style" aria-label="Permalink to &quot;Tape style&quot;">​</a></h4><p>Як принти угод розташовані на стрічці.</p><table tabindex="0"><thead><tr><th>Варіант</th><th>Поведінка</th></tr></thead><tbody><tr><td><strong>Default</strong></td><td>По одному блоку на угоду — лінія рухається лише коли друкується нова угода.</td></tr><tr><td><strong>Continuous</strong></td><td>Рівномірні комірки, але вся лінія рухається безперервно.</td></tr><tr><td><strong>Overlap</strong></td><td>Кожна угода стоїть на своєму реальному часі, тож угоди накладаються.</td></tr></tbody></table><h4 id="tape-speed" tabindex="-1">Tape speed <a class="header-anchor" href="#tape-speed" aria-label="Permalink to &quot;Tape speed&quot;">​</a></h4><p>За скільки лінія угод виходить за межі видимості. Діапазон <strong>від 1 до 15 секунд</strong>, за замовчуванням 7.</p><p>Показується лише для стилів <strong>Continuous</strong> і <strong>Overlap</strong> — стиль Default рухається за принтами, а не за часом, тож швидкість до нього не застосовується.</p><h2 id="торгівля" tabindex="-1">Торгівля <a class="header-anchor" href="#торгівля" aria-label="Permalink to &quot;Торгівля&quot;">​</a></h2><h3 id="вибір-маиданчика" tabindex="-1">Вибір майданчика <a class="header-anchor" href="#вибір-маиданчика" aria-label="Permalink to &quot;Вибір майданчика&quot;">​</a></h3><p>Майданчик задається <strong>для кожної панелі окремо</strong>, кнопкою майданчика в заголовку панелі. Можна тримати кілька панелей на різних майданчиках одночасно.</p><p>Перемикання майданчика зі збереженням поточної монети підставляє пару до USDT цього майданчика. Якщо ж обрати ринок із пошуку, переноситься його справжній символ, тож пари без USDT — як <code>ETH/BTC</code> чи <code>SOL/USDC</code> — працюють, а не переписуються мовчки на USDT-пару.</p><h3 id="торгівля-кліком" tabindex="-1">Торгівля кліком <a class="header-anchor" href="#торгівля-кліком" aria-label="Permalink to &quot;Торгівля кліком&quot;">​</a></h3><p>Драбина цін і є введенням ордерів. Куди ви клацаєте і якою кнопкою миші — визначає і сторону, і тип ордера:</p><table tabindex="0"><thead><tr><th>Дія</th><th>Позиція рядка</th><th>Результат</th></tr></thead><tbody><tr><td><strong>Лівий клік</strong></td><td>На стороні asks (вище спреду)</td><td><strong>Ринкова покупка</strong></td></tr><tr><td><strong>Лівий клік</strong></td><td>На стороні bids або в спреді</td><td><strong>Лімітна покупка</strong> за цією ціною</td></tr><tr><td><strong>Правий клік</strong></td><td>На стороні bids (нижче спреду)</td><td><strong>Ринковий продаж</strong></td></tr><tr><td><strong>Правий клік</strong></td><td>На стороні asks або в спреді</td><td><strong>Лімітний продаж</strong> за цією ціною</td></tr></tbody></table><p>Коротко: <strong>лівий клік купує, правий продає.</strong> Клік <em>через</em> спред — покупка в asks або продаж у bids — перетинає стакан і виконується одразу як ринковий ордер. Клік на своїй стороні лишає лімітний ордер.</p><p>Ринкові ордери надсилаються як immediate-or-cancel і проходять крізь протилежну сторону стакана.</p><p>Ордери спрацьовують по кліку без підтвердження. Повторні кліки протягом 120 мс ігноруються — це рятує від випадкового подвійного спрацювання, але не заважає свідомому другому кліку.</p><p>Щойно виставлений ордер одразу малюється на драбині як <strong>ghost order</strong>, ще до підтвердження біржею, щоб ви бачили, що надіслали. Помилки з&#39;являються спливаючим повідомленням у вікні.</p><h3 id="sl-tp" tabindex="-1">SL / TP <a class="header-anchor" href="#sl-tp" aria-label="Permalink to &quot;SL / TP&quot;">​</a></h3><p>Утримуйте клавішу <strong>Place SL / TP at row</strong> (за замовчуванням <kbd>A</kbd>) і клацніть рядок драбини, щоб поставити стоп-лос або тейк-профіт за цією ціною.</p><p>Наявні позначки SL/TP мають держак на бічній смузі, за який їх можна тягнути. При відпусканні тригер переставляється на рядок під курсором — спершу ставиться новий, потім скасовується старий. Перетягування тригера через ціну входу автоматично <strong>міняє SL ↔ TP</strong>, щоб умова тригера лишалася коректною.</p><h3 id="тригернии-вхід" tabindex="-1">Тригерний вхід <a class="header-anchor" href="#тригернии-вхід" aria-label="Permalink to &quot;Тригерний вхід&quot;">​</a></h3><p>Утримуйте клавішу <strong>Arm trigger entry at row</strong> (за замовчуванням <kbd>S</kbd>) і клацніть рядок драбини, щоб зарядити вхід, який спрацює, коли ціна його досягне. Лівий клік заряджає покупку, правий — продаж.</p><h2 id="клавіші" tabindex="-1">Клавіші <a class="header-anchor" href="#клавіші" aria-label="Permalink to &quot;Клавіші&quot;">​</a></h2><p>Кожне скорочення нижче можна перепризначити: відкрийте секцію <strong>Keybinds</strong>, клацніть кнопку клавіші й натисніть нову. <kbd>Esc</kbd> скасовує. Кнопка <strong>Reset</strong> повертає всі значення за замовчуванням.</p><p>Прив&#39;язки зберігаються як фізичні позиції клавіш, тож вони переживають зміну розкладки клавіатури.</p><h3 id="торгівля-1" tabindex="-1">Торгівля <a class="header-anchor" href="#торгівля-1" aria-label="Permalink to &quot;Торгівля&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Дія</th><th>За замовчуванням</th></tr></thead><tbody><tr><td>Скасувати всі ордери</td><td><kbd>Space</kbd></td></tr><tr><td>Закрити позицію (ринком)</td><td><kbd>W</kbd></td></tr><tr><td>Розвернути позицію</td><td><kbd>Tab</kbd></td></tr><tr><td>Пошук тікера</td><td><kbd>F</kbd></td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Скасування всіх ордерів, закриття та розворот позиції діють миттєво на активному наборі ключів, без жодного підтвердження.</p></div><h3 id="розмір-ордера" tabindex="-1">Розмір ордера <a class="header-anchor" href="#розмір-ордера" aria-label="Permalink to &quot;Розмір ордера&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Дія</th><th>За замовчуванням</th></tr></thead><tbody><tr><td>Обрати пресет 1–5</td><td><kbd>1</kbd> … <kbd>5</kbd></td></tr></tbody></table><h3 id="драбина" tabindex="-1">Драбина <a class="header-anchor" href="#драбина" aria-label="Permalink to &quot;Драбина&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Дія</th><th>За замовчуванням</th></tr></thead><tbody><tr><td>Відцентрувати на best bid/ask</td><td><kbd>Shift</kbd> (лівий)</td></tr><tr><td>Більший крок ціни</td><td><kbd>=</kbd></td></tr><tr><td>Менший крок ціни</td><td><kbd>-</kbd></td></tr><tr><td>Змінити крок ціни</td><td><kbd>R</kbd> + прокрутка</td></tr><tr><td>Змінити межу смуги обсягу</td><td><kbd>D</kbd> + прокрутка</td></tr><tr><td>Поставити SL / TP на рядку</td><td><kbd>A</kbd> + клік</td></tr><tr><td>Зарядити тригерний вхід</td><td><kbd>S</kbd> + клік / правий клік</td></tr></tbody></table><p>Скорочення для рисування на графіках — промінь, лінія, магніт — <strong>не</strong> налаштовуються тут. Вони у вкладці Home; див. <a href="/manual/uk/customize/chart-colors.html">Графіки та рисування</a>.</p><h2 id="вигляд" tabindex="-1">Вигляд <a class="header-anchor" href="#вигляд" aria-label="Permalink to &quot;Вигляд&quot;">​</a></h2><p>Секція <strong>Appearance</strong> змінює вигляд драбини. Кнопка <strong>Reset</strong> повертає всі значення на цій сторінці до типових.</p><h3 id="layout" tabindex="-1">Layout <a class="header-anchor" href="#layout" aria-label="Permalink to &quot;Layout&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Налаштування</th><th>Що робить</th><th>Діапазон</th><th>За замовчуванням</th></tr></thead><tbody><tr><td><strong>Text size</strong></td><td>Розмір шрифту рядка драбини</td><td>9–18px</td><td>12px</td></tr><tr><td><strong>Row height</strong></td><td>Висота рядка драбини</td><td>8–20px</td><td>12px</td></tr><tr><td><strong>Big-volume threshold</strong></td><td>Заповнення смуги у %, після якого вмикається колір «Volume big»</td><td>10–95%, крок 5</td><td>60%</td></tr></tbody></table><p>Смуга глибини із заповненням 100% завжди використовує колір <strong>Volume full</strong>, незалежно від цього порогу.</p><h3 id="кольори" tabindex="-1">Кольори <a class="header-anchor" href="#кольори" aria-label="Permalink to &quot;Кольори&quot;">​</a></h3><p><strong>Background</strong> — один колір фону стакана (за замовчуванням <code>#181818</code>). Свою непрозорість він тримає всередині hex, як і решта застосунку.</p><p>Решта згрупована, і кожен запис зберігає колір і непрозорість <strong>двома окремими значеннями</strong> — саме тому ця панель, єдина в Warden, показує відсоток поруч із кожним записом:</p><table tabindex="0"><thead><tr><th>Група</th><th>Записи</th></tr></thead><tbody><tr><td><strong>Order book</strong></td><td>Bid, Ask, Best bid, Best ask, Price</td></tr><tr><td><strong>Volume bars</strong></td><td>Volume bar, Volume big, Volume full</td></tr><tr><td><strong>Position &amp; orders</strong></td><td>Placed order, Stop-loss, Take-profit, Position +PnL, Position −PnL</td></tr><tr><td><strong>Trade tape</strong></td><td>Tape buy, Tape sell</td></tr><tr><td><strong>General</strong></td><td>Text, Row hover</td></tr></tbody></table><p>Три кольори смуг обсягу утворюють прогресію: смуга використовує <strong>Volume bar</strong> нижче порогу великого обсягу, <strong>Volume big</strong> вище нього і <strong>Volume full</strong>, коли заповнює рядок повністю. Три різні кольори роблять відносну глибину зрозумілою з першого погляду.</p><p><strong>Position +PnL</strong> і <strong>Position −PnL</strong> заливають смугу позиції залежно від того, у прибутку вона зараз чи у збитку.</p><h2 id="налаштування-для-кожного-тікера" tabindex="-1">Налаштування для кожного тікера <a class="header-anchor" href="#налаштування-для-кожного-тікера" aria-label="Permalink to &quot;Налаштування для кожного тікера&quot;">​</a></h2><p>Крок ціни та межа смуги обсягу зберігаються <strong>для кожної монети окремо</strong>, а не глобально — налаштувавши драбину для BTC, ви не змінюєте вигляд ETH. Це задається з вікна клавішами драбини вище, а не з вкладки налаштувань.</p><h2 id="пов-язане" tabindex="-1">Пов&#39;язане <a class="header-anchor" href="#пов-язане" aria-label="Permalink to &quot;Пов&#39;язане&quot;">​</a></h2><ul><li><a href="/manual/uk/getting-started.html">Початок роботи</a> — решта Warden, яка не потребує ключів і не може торгувати</li></ul>',54))])}const k=d(i,[["render",l]]);export{m as __pageData,k as default};
